/**
 * The contract between the engine, the daemon and the UI.
 * Change this first, then update fixtures/mock so the frontend keeps working.
 */
import { z } from "zod";

/** Mabel-style verdicts, ordered from worst to best. */
export const VERDICTS = ["reject", "defer", "approve", "endorse"] as const;
export const Verdict = z.enum(VERDICTS);
export type Verdict = z.infer<typeof Verdict>;

/** Worst wins: any reject blocks, however many approvals surround it. */
export function worstVerdict(verdicts: readonly Verdict[]): Verdict {
  const rank = (v: Verdict) => VERDICTS.indexOf(v);
  return verdicts.reduce<Verdict>((w, v) => (rank(v) < rank(w) ? v : w), "endorse");
}

/** Where a decision came from, relative to what the human asked for. */
export const Origin = z.enum(["requested", "inferred", "silent"]);
export type Origin = z.infer<typeof Origin>;

export const CodeLocation = z.object({
  file: z.string(),
  lines: z.tuple([z.number().int().positive(), z.number().int().positive()]),
});
export type CodeLocation = z.infer<typeof CodeLocation>;

/** One decision found in a change. Produced by a check, ranked by risk. */
export const Claim = z.object({
  id: z.string(),
  check: z.string(),
  summary: z.string(),
  origin: Origin,
  symbols: z.array(z.string()),
  location: CodeLocation,
  evidence: z.string(),
});
export type Claim = z.infer<typeof Claim>;

export const RiskInputs = z.object({
  blastRadius: z.number().min(0),
  originWeight: z.number().min(0),
  untested: z.number().min(0).max(1),
  mastery: z.number().min(0).max(1),
});
export type RiskInputs = z.infer<typeof RiskInputs>;

export const RankedClaim = Claim.extend({ risk: z.number().min(0), inputs: RiskInputs });
export type RankedClaim = z.infer<typeof RankedClaim>;

/** Model output for a check. Parsed before use, never trusted as prose. */
export const CheckResult = z.object({ claims: z.array(Claim.omit({ id: true, check: true })) });
export type CheckResult = z.infer<typeof CheckResult>;

export const Question = z.object({
  id: z.string(),
  claimId: z.string(),
  ask: z.string(),
  mustMention: z.array(z.string()).min(1),
  followUpIfVague: z.string(),
  location: CodeLocation,
});
export type Question = z.infer<typeof Question>;

export const ExamPlan = z.object({ questions: z.array(Question).max(3) });
export type ExamPlan = z.infer<typeof ExamPlan>;

export const AnswerMode = z.enum(["voice", "typed"]);
export const Answer = z.object({
  questionId: z.string(),
  transcript: z.string(),
  mode: AnswerMode,
});
export type Answer = z.infer<typeof Answer>;

/** The grader sees the transcript and rubric only. Accent and fluency cannot reach it. */
export const Grade = z.object({
  questionId: z.string(),
  verdict: Verdict,
  score: z.number().min(0).max(1),
  missing: z.array(z.string()),
});
export type Grade = z.infer<typeof Grade>;

export const ReviewStage = z.enum([
  "collecting",
  "prechecks",
  "injection-scan",
  "checks",
  "planning",
  "awaiting-exam",
  "grading",
  "done",
]);
export type ReviewStage = z.infer<typeof ReviewStage>;

/** Why the gate decided what it did. Safe to log: it holds no diff or prose. */
export const GateReason = z.enum([
  "docs-only",
  "low-risk",
  "earned-trust",
  "too-large",
  "injection-suspected",
  "viva-config-changed",
  "exam-passed",
  "exam-failed",
  "skipped-with-debt",
  "pipeline-error",
]);
export type GateReason = z.infer<typeof GateReason>;

export const Gate = z.object({
  verdict: Verdict,
  reason: GateReason,
  /** False for hard gates, which config and "skip with debt" cannot bypass. */
  skippable: z.boolean(),
});
export type Gate = z.infer<typeof Gate>;

export const ReviewRequest = z.object({
  repoPath: z.string(),
  base: z.string(),
  head: z.string(),
  person: z.string(),
  intent: z.string().optional(),
});
export type ReviewRequest = z.infer<typeof ReviewRequest>;

export const Usage = z.object({
  inputTokens: z.number().int().nonnegative(),
  outputTokens: z.number().int().nonnegative(),
  llmCalls: z.number().int().nonnegative(),
});
export type Usage = z.infer<typeof Usage>;

export const Review = z.object({
  id: z.string(),
  request: ReviewRequest,
  stage: ReviewStage,
  claims: z.array(RankedClaim),
  plan: ExamPlan.nullable(),
  grades: z.array(Grade),
  gate: Gate.nullable(),
  usage: Usage,
  startedAt: z.string(),
  finishedAt: z.string().nullable(),
});
export type Review = z.infer<typeof Review>;

/** Local retry receipt: no questions, model prose, diffs or answers on disk. */
export const ReviewDecision = z.object({
  key: z.string().regex(/^[a-f0-9]{64}$/),
  reviewId: z.string().uuid(),
  gate: Gate,
  finishedAt: z.string(),
});
export type ReviewDecision = z.infer<typeof ReviewDecision>;

/** On-demand feedback stays in the review; it never enters the ledger. */
export const ReviewFeedback = z.object({
  reviewId: z.string(),
  gate: Gate,
  items: z.array(z.object({
    questionId: z.string(),
    location: CodeLocation,
    ask: z.string(),
    missing: z.array(z.string()),
  })),
});
export type ReviewFeedback = z.infer<typeof ReviewFeedback>;

/**
 * One line of the ledger. Mirrors Mabel's data boundary: scores and hashes
 * leave the review, while diffs, transcripts and model output do not.
 */
export const Attestation = z.object({
  person: z.string(),
  symbol: z.string(),
  file: z.string(),
  codeHash: z.string(),
  score: z.number().min(0).max(1),
  at: z.string(),
  reviewId: z.string(),
});
export type Attestation = z.infer<typeof Attestation>;

export const FogNode = z.object({
  id: z.string(),
  file: z.string(),
  symbol: z.string().nullable(),
  size: z.number().nonnegative(),
  blastRadius: z.number().nonnegative(),
  /** 0 is fully understood, 1 is understood by nobody. */
  fog: z.number().min(0).max(1),
  knownBy: z.array(z.object({ person: z.string(), mastery: z.number().min(0).max(1) })),
});
export type FogNode = z.infer<typeof FogNode>;

export const FogMap = z.object({
  generatedAt: z.string(),
  debt: z.number().nonnegative(),
  nodes: z.array(FogNode),
});
export type FogMap = z.infer<typeof FogMap>;
import { fileURLToPath } from "node:url";
import { Answer, ReviewFeedback, ReviewRequest, type Review } from "@viva/contracts";
import {
  appendAttestations,
  computeFog,
  entireSource,
  GeminiProvider,
  grepBlastRadius,
  loadChecks,
  loadFogFiles,
  MockProvider,
  readLedger,
  skipWithDebt,
  startReview,
  submitAnswers,
  type LlmProvider,
} from "@viva/engine";
import { Hono } from "hono";
import { z } from "zod";
import { decisionIdentity, readDecision, writeDecision } from "./decisions.js";

export function createProvider(env: NodeJS.ProcessEnv = process.env): LlmProvider {
  if (env.VIVA_LLM === "gemini") {
    if (!env.GEMINI_API_KEY || !env.GEMINI_MODEL) throw new Error("set GEMINI_API_KEY and GEMINI_MODEL");
    return new GeminiProvider(env.GEMINI_API_KEY, env.GEMINI_MODEL, env.GEMINI_FALLBACK_MODEL);
  }
  return new MockProvider();
}

const CHECKS_DIR = fileURLToPath(new URL("../../../checks", import.meta.url));

/**
 * The daemon only tracks reviews and serves the UI. Reviews stay on this
 * machine, and only attestations leave it, inside git notes.
 */
export function createApp(llm: LlmProvider = createProvider()) {
  const reviews = new Map<string, Review>();
  const byKey = new Map<string, Promise<Review>>();
  const changing = new Set<string>();
  const app = new Hono();

  app.get("/v1/health", (c) => c.json({ ok: true, llm: llm.id }));

  app.post("/v1/reviews", async (c) => {
    const { request, key, dir } = await decisionIdentity(ReviewRequest.parse(await c.req.json()));
    let pending = byKey.get(key);
    if (!pending) {
      pending = (async () => {
        const receipt = await readDecision(dir, key);
        const review: Review = receipt ? {
          id: receipt.reviewId, request, stage: "done", claims: [], plan: null, grades: [],
          gate: receipt.gate, usage: { inputTokens: 0, outputTokens: 0, llmCalls: 0 },
          startedAt: receipt.finishedAt, finishedAt: receipt.finishedAt,
        } : await startReview(request, {
          llm,
          checks: await loadChecks(CHECKS_DIR),
          session: entireSource,
          blast: grepBlastRadius,
          ledger: await readLedger(request.repoPath),
        });
        if (!receipt) await writeDecision(review);
        reviews.set(review.id, review);
        return review;
      })();
      byKey.set(key, pending);
      // Allow a retry after an infrastructure failure.
      pending.catch(() => byKey.delete(key));
    }
    const initial = await pending;
    const review = reviews.get(initial.id) ?? initial;
    return c.json(review);
  });

  app.get("/v1/reviews", (c) => c.json([...reviews.values()].reverse()));

  app.get("/v1/reviews/:id", (c) => {
    const review = reviews.get(c.req.param("id"));
    return review ? c.json(review) : c.json({ error: "review not found; retry git push to refresh it after a daemon restart" }, 404);
  });

  app.post("/v1/reviews/:id/answers", async (c) => {
    const answers = z.array(Answer).parse(await c.req.json());
    const current = reviews.get(c.req.param("id"));
    if (!current) return c.json({ error: "not found" }, 404);
    if (current.stage !== "awaiting-exam" || changing.has(current.id)) {
      return c.json({ error: "review is not awaiting an exam" }, 409);
    }
    changing.add(current.id);
    try {
      const { review, attestations } = await submitAnswers(current, answers, { llm });
      await appendAttestations(review.request.repoPath, review.request.head, attestations);
      await writeDecision(review);
      reviews.set(review.id, review);
      return c.json(review);
    } finally {
      changing.delete(current.id);
    }
  });

  app.post("/v1/reviews/:id/skip", async (c) => {
    const current = reviews.get(c.req.param("id"));
    if (!current) return c.json({ error: "not found" }, 404);
    if (current.gate?.skippable === false || changing.has(current.id)) {
      return c.json({ error: "this gate cannot be skipped" }, 409);
    }
    const review = skipWithDebt(current);
    changing.add(current.id);
    try {
      await writeDecision(review);
      reviews.set(review.id, review);
      return c.json(review);
    } finally {
      changing.delete(current.id);
    }
  });

  app.get("/v1/reviews/:id/feedback", (c) => {
    const review = reviews.get(c.req.param("id"));
    if (!review) return c.json({ error: "review not found; retry git push after a daemon restart" }, 404);
    if (!review.gate) return c.json({ error: "complete the exam first" }, 409);
    if (review.gate.reason.startsWith("exam-") && review.grades.length === 0) {
      return c.json({ error: "feedback expired on daemon restart; only the gate decision was retained" }, 410);
    }
    return c.json(ReviewFeedback.parse({
      reviewId: review.id, gate: review.gate,
      items: review.grades.flatMap((grade) => {
        const question = review.plan?.questions.find((q) => q.id === grade.questionId);
        return question && grade.missing.length ? [{
          questionId: question.id, location: question.location, ask: question.ask, missing: grade.missing,
        }] : [];
      }),
    }));
  });

  app.get("/v1/fog", async (c) => {
    const repoPath = c.req.query("repo") ?? process.cwd();
    return c.json(computeFog(await loadFogFiles(repoPath), await readLedger(repoPath), new Date()));
  });

  app.onError((error, c) => {
    // Errors from a provider may contain model/repository text. Never log it.
    console.error("vivad: request failed");
    return c.json({ error: "Viva request failed" }, 500);
  });

  return app;
}
import { FogMap, Review, type Answer } from "@viva/contracts";
import mockFog from "../../../../fixtures/mock/fog.json";
import mockReview from "../../../../fixtures/mock/review.json";

/** Mock mode lets the UI run with no daemon: add ?mock to the URL. */
const MOCK = new URLSearchParams(location.search).has("mock");

async function json(path: string, init?: RequestInit): Promise<unknown> {
  const response = await fetch(path, init);
  if (!response.ok) throw new Error(`${path} returned ${response.status}`);
  return response.json();
}

export async function getFog(): Promise<FogMap> {
  return FogMap.parse(MOCK ? mockFog : await json("/v1/fog"));
}

export async function getReview(id: string | null): Promise<Review> {
  if (MOCK || !id) return Review.parse(mockReview);
  return Review.parse(await json(`/v1/reviews/${id}`));
}

export async function submitAnswers(id: string, answers: Answer[]): Promise<Review> {
  if (MOCK) return Review.parse({ ...mockReview, stage: "done", gate: { verdict: "approve", reason: "exam-passed", skippable: true } });
  return Review.parse(
    await json(`/v1/reviews/${id}/answers`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(answers),
    }),
  );
}
